address public immutable guardian; struct Halt { uint64 from; uint64 until; } Halt[] private _halts; uint256 internal constant MAX_HALT = 36 hours;
function halt(uint64 until) external {
  if (msg.sender != guardian) revert CallerNotGuardian(msg.sender);
  if (until <= block.timestamp || until > block.timestamp + MAX_HALT) revert InvalidHalt(until);
  uint256 n = _halts.length;
  if (n != 0 && _halts[n-1].until > block.timestamp) { if (until <= _halts[n-1].until) revert InvalidHalt(until); _halts[n-1].until = until; }
  else _halts.push(Halt(uint64(block.timestamp), until));
  emit Halted(_halts[_halts.length-1].from, until, _bumpVersion());
}

