Bind the module to one SleeveTimelock at its floor, and harden SleeveTimelock's constructor. This follows D-019's reason for checking immutables in the constructor.

```solidity
// ISleeveModule
error TimelockMismatch(address tokenSourceTimelock, address calendarTimelock);
error TimelockNotSleeve(address timelock);

// SleeveModule.sol, file scope
interface ISleeveTimelockViews {
    function MIN_DELAY_FLOOR() external view returns (uint256);
    function getMinDelay() external view returns (uint256);
}
uint256 private constant TIMELOCK_FLOOR = 172_800;

// constructor, after RouterFactoryMismatch:
_requireTimelock(config.tokenSource.timelock(), config.calendar.timelock());

function _requireTimelock(address t, address c) private view {
    if (t != c) revert TimelockMismatch(t, c);
    if (t.code.length <= 23) revert TimelockNotSleeve(t); // EOA or EIP-7702 designator
    (bool ok, bytes memory floor) = t.staticcall(abi.encodeCall(ISleeveTimelockViews.MIN_DELAY_FLOOR, ()));
    if (!ok || floor.length != 32 || abi.decode(floor, (uint256)) != TIMELOCK_FLOOR) revert TimelockNotSleeve(t);
    if (ISleeveTimelockViews(t).getMinDelay() < TIMELOCK_FLOOR) revert TimelockNotSleeve(t);
}

// SleeveTimelock
error NoRoleHolder();
error ZeroRoleHolder();
// constructor: _requireHolders(proposers); _requireHolders(executors);
function _requireHolders(address[] memory h) private pure {
    if (h.length == 0) revert NoRoleHolder();
    for (uint256 i; i < h.length; ++i) if (h[i] == address(0)) revert ZeroRoleHolder();
}
```

